export const PLATFORMS={bilibili:'B站'};
export const SOURCES={following:'关注更新',favorites:'我的收藏',watchlater:'稍后再看',ranking:'榜单候选'};
export const TIERS=['S','A','B','C'];
export const WEIGHTS={S:10,A:6,B:3,C:1,'':1};
export const clean=(s,n=4000)=>typeof s==='string'?s.trim().slice(0,n):'';
export function platformURL(value){let u;try{u=new URL(value);}catch{throw new Error('需要完整HTTPS视频地址');}if(u.protocol!=='https:'||u.username||u.password)throw new Error('链接必须为不含账号信息的HTTPS地址');if(!['bilibili.com','www.bilibili.com'].includes(u.hostname)||!/^\/video\/BV[A-Za-z0-9]+\/?$/.test(u.pathname))throw new Error('当前版本仅接入B站BV视频');const id=u.pathname.match(/BV[A-Za-z0-9]+/)[0];return {platform:'bilibili',id,url:`https://www.bilibili.com/video/${id}`};}
export function seconds(v){if(typeof v==='number')return Number.isFinite(v)&&v>=0?Math.round(v):null;if(typeof v!=='string'||!/^\d{1,3}(?::\d{2}){1,2}$/.test(v))return null;const p=v.split(':').map(Number);return p.slice(1).some(n=>n>59)?null:p.reduce((a,b)=>a*60+b,0);}
export function formatDuration(v){if(v===null||v===undefined)return '';v=Math.max(0,Math.floor(v));return v>=3600?`${Math.floor(v/3600)}:${String(Math.floor(v%3600/60)).padStart(2,'0')}:${String(v%60).padStart(2,'0')}`:`${Math.floor(v/60)}:${String(v%60).padStart(2,'0')}`;}
export function safeCover(v){const s=clean(v);if(/^private\/[\w./-]+$/.test(s)&&!s.includes('..'))return s;try{const u=new URL(s);return u.protocol==='https:'&&!u.username&&!u.password?u.href:'';}catch{return '';}}
export function normalizeLibrary(input,policy={}){
 if(!input||typeof input!=='object')throw new Error('请导入JSON对象或视频数组');if(!Array.isArray(input)&&input.schemaVersion!==undefined&&input.schemaVersion!==1)throw new Error('不支持这个数据版本');const rows=Array.isArray(input)?input:input.videos;if(!Array.isArray(rows))throw new Error('需要videos数组');if(rows.length>100000)throw new Error('单次最多100000条');
 const excluded=new Set(policy.excludedCollections||[]),approved=new Set(policy.publicCollections||[]),videos=[],errors=[],seen=new Map(),skipped={platform:0,private:0,unverified:0,invalid:0};let duplicates=0;
 for(const [i,r] of rows.entries()){try{
  if(!r||typeof r!=='object')throw new Error('视频条目需要是对象');
  if(r.platform==='douyin'||/^https:\/\/(www\.)?douyin\.com\//.test(r.url||'')){skipped.platform++;continue;}
  const link=platformURL(r.url);if((policy.excludedVideoIds||[]).includes(link.id)){skipped.private++;continue;}if(r.platform&&r.platform!==link.platform)throw new Error('平台与链接不一致');
  if(r.visibility==='private'||r.isPrivate===true){skipped.private++;continue;}
  let collections=(Array.isArray(r.collections)?r.collections:[r.collection]).map(x=>clean(x,80)).filter(Boolean);
  const hadExcluded=collections.some(c=>excluded.has(c));collections=collections.filter(c=>!excluded.has(c));
  if(hadExcluded&&!collections.length){skipped.private++;continue;}
  if(r.visibility!=='public'){collections=collections.filter(c=>approved.has(c));if(!collections.length){skipped.unverified++;continue;}}
  const title=clean(r.title,1000);if(title==='已失效视频'){skipped.invalid++;continue;}if(!title)throw new Error('缺少标题');
  const sources=[...new Set((Array.isArray(r.sources)?r.sources:[r.source||'favorites']).filter(s=>Object.hasOwn(SOURCES,s)))];if(!sources.length)throw new Error('来源仅支持following、favorites、watchlater、ranking');
  const key=`bilibili:${link.id}`,author=clean(r.author,120)||'作者未记录';const creatorId=clean(r.creatorId,40);const creatorKey=`up:${creatorId||author}`;
  const v={...link,key,contributors:[...new Set((Array.isArray(r.contributors)?r.contributors:[]).map(x=>clean(x,40)).filter(x=>/^\d+$/.test(x)))],publishedAtLabel:clean(r.publishedAtLabel,100),ranking:r.ranking&&typeof r.ranking==='object'?{name:clean(r.ranking.name,80),rank:Number.isInteger(r.ranking.rank)&&r.ranking.rank>0?r.ranking.rank:null,capturedAt:clean(r.ranking.capturedAt,40)}:null,title,author,creatorId,creatorKey,authorUrl:creatorId&&/^\d+$/.test(creatorId)?`https://space.bilibili.com/${creatorId}`:'',cover:safeCover(r.cover),duration:seconds(r.duration),visibility:'public',collections:[...new Set(collections)],sources,tags:[...new Set((Array.isArray(r.tags)?r.tags:[]).map(x=>clean(x,40)).filter(Boolean).slice(0,12))],description:clean(r.description,12000),publishedAt:clean(r.publishedAt,60),collectedAt:clean(r.collectedAt,60),views:Number.isFinite(r.views)&&r.views>=0?r.views:null};
  if(seen.has(key)){duplicates++;const old=videos[seen.get(key)];old.collections=[...new Set([...old.collections,...v.collections])];old.sources=[...new Set([...old.sources,...v.sources])];old.contributors=[...new Set([...old.contributors,...v.contributors])];if(!old.ranking&&v.ranking)old.ranking=v.ranking;old.tags=[...new Set([...old.tags,...v.tags])];continue;}seen.set(key,videos.length);videos.push(v);
 }catch(e){errors.push(`第${i+1}条：${e.message}`);}}
 const followedCreators=[...new Map((Array.isArray(input.followedCreators)?input.followedCreators:[]).filter(c=>/^\d+$/.test(String(c.id))&&clean(c.name,120)).map(c=>[String(c.id),{id:String(c.id),name:clean(c.name,120),profileStatus:['read','unavailable','no-public-uploads'].includes(c.profileStatus)?c.profileStatus:'unverified',lastUploadAt:/^\d{4}-\d{2}-\d{2}$/.test(c.lastUploadAt||'')?c.lastUploadAt:'',recentVideoAfter:/^\d{4}-\d{2}-\d{2}$/.test(c.recentVideoAfter||'')?c.recentVideoAfter:'',activityCheckedAt:clean(c.activityCheckedAt,40),activityEvidence:clean(c.activityEvidence,200)}])).values()];
 return {library:{followedCreators,schemaVersion:1,title:clean(input.title,80)||'我的频道',owner:clean(input.owner,60)||'我',revision:clean(input.revision,80),updatedAt:clean(input.updatedAt,60),provenance:input.provenance&&typeof input.provenance==='object'?{method:clean(input.provenance.method,200),scope:clean(input.provenance.scope,500),complete:input.provenance.complete===true}:null,videos},errors,skipped,duplicates};
}
export function mergeLibraries(a,b){const map=new Map(a.videos.map(v=>[v.key,v]));let added=0,updated=0;for(const v of b.videos){const old=map.get(v.key);if(old){updated++;map.set(v.key,{...old,...v,creatorId:v.creatorId||old.creatorId,creatorKey:v.creatorId?v.creatorKey:old.creatorKey,authorUrl:v.authorUrl||old.authorUrl,duration:v.duration??old.duration,ranking:v.ranking||old.ranking,contributors:[...new Set([...(old.contributors||[]),...(v.contributors||[])])],cover:v.cover||old.cover,collections:[...new Set([...old.collections,...v.collections])],sources:[...new Set([...old.sources,...v.sources])],tags:[...new Set([...old.tags,...v.tags])]});}else{map.set(v.key,v);added++;}}return {library:{...a,...b,title:a.title,owner:a.owner,followedCreators:b.followedCreators?.length?b.followedCreators:(a.followedCreators||[]),provenance:b.provenance||a.provenance,videos:[...map.values()]},added,updated};}
export function buildCreators(videos,prefs={},roster=[]){if(roster.length)return roster.map(c=>{const key='up:'+c.id,p=prefs[key]||{};return {key,name:c.name,url:'https://space.bilibili.com/'+c.id,count:videos.filter(v=>v.creatorId===c.id||(v.contributors||[]).includes(c.id)).length,tier:TIERS.includes(p.tier)?p.tier:'',reason:clean(p.reason,500)};}).sort((a,b)=>WEIGHTS[b.tier]-WEIGHTS[a.tier]||a.name.localeCompare(b.name,'zh-CN'));const map=new Map();for(const v of videos){if(!map.has(v.creatorKey)){const p=prefs[v.creatorKey]||{};map.set(v.creatorKey,{key:v.creatorKey,name:v.author,url:v.authorUrl,count:0,tier:TIERS.includes(p.tier)?p.tier:'',reason:clean(p.reason,500)});}map.get(v.creatorKey).count++;}return [...map.values()].sort((a,b)=>WEIGHTS[b.tier]-WEIGHTS[a.tier]||a.name.localeCompare(b.name,'zh-CN'));}
export function filterVideos(videos,{query='',creator='',tier='all',source='all',status='all',duration='all',includeRanking=false,sort='feed'}={},prefs={},creatorPrefs={}){const terms=query.toLowerCase().trim().split(/\s+/).filter(Boolean);const out=videos.filter(v=>{const p=prefs[v.key]||{},grade=creatorPrefs[v.creatorKey]?.tier||'';if(creator&&v.creatorKey!==creator&&!(v.contributors||[]).some(id=>'up:'+id===creator))return false;if(tier!=='all'&&(tier==='unrated'?grade!=='':grade!==tier))return false;if(source!=='all'&&!v.sources.includes(source))return false;if(!includeRanking&&v.sources.every(s=>s==='ranking'))return false;if(status==='watched'&&!p.watched||status==='unwatched'&&p.watched||status==='starred'&&!p.starred)return false;if(duration==='short'&&(v.duration===null||v.duration>600)||duration==='medium'&&(v.duration===null||v.duration<=600||v.duration>1800)||duration==='long'&&(v.duration===null||v.duration<=1800))return false;return terms.every(t=>[v.title,v.author,v.description,...v.collections,...v.tags,p.note||''].join(' ').toLowerCase().includes(t));});if(sort==='short')out.sort((a,b)=>(a.duration??Infinity)-(b.duration??Infinity));if(sort==='long')out.sort((a,b)=>(b.duration??-1)-(a.duration??-1));if(sort==='latest')out.sort((a,b)=>(Date.parse(b.publishedAt)||0)-(Date.parse(a.publishedAt)||0));return out;}
const shuffle=(a,rng)=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
function weighted(items,weight,rng){const total=items.reduce((s,x)=>s+weight(x),0);let r=rng()*total;for(const x of items){r-=weight(x);if(r<0)return x;}return items.at(-1);}
export function buildHomeFeed(videos,creatorPrefs={},rng=Math.random,{includeRanking=false}={}){
 const sourceWeights={following:.5,favorites:.3,watchlater:.15,ranking:.05},pools=new Map();
 for(const source of Object.keys(SOURCES)){if(source==='ranking'&&!includeRanking)continue;const groups=new Map();for(const v of videos){if(!v.sources.includes(source))continue;if(!groups.has(v.creatorKey))groups.set(v.creatorKey,[]);groups.get(v.creatorKey).push(v);}pools.set(source,[...groups].map(([creator,rows])=>({creator,rows:shuffle(rows,rng)})));}
 const seen=new Set(),out=[];for(let i=0;i<Math.min(videos.length,600);i++){
  for(const [s,groups] of pools){for(const g of groups){while(g.rows.length&&seen.has(g.rows.at(-1).key))g.rows.pop();}pools.set(s,groups.filter(g=>g.rows.length));}
  const sources=[...pools].filter(([,gs])=>gs.length);if(!sources.length)break;const [s,gs]=weighted(sources,x=>sourceWeights[x[0]],rng);const g=weighted(gs,x=>WEIGHTS[creatorPrefs[x.creator]?.tier||'']||1,rng);const v=g.rows.pop();seen.add(v.key);out.push(v);
 }
 return out.concat(shuffle(videos.filter(v=>!seen.has(v.key)&&(includeRanking||!v.sources.every(s=>s==='ranking'))),rng));
}
export function cleanPreferences(prefs,library){const keys=new Set(library.videos.map(v=>v.key));return Object.fromEntries(Object.entries(prefs||{}).filter(([k])=>keys.has(k)).map(([k,p])=>[k,{watched:p?.watched===true,starred:p?.starred===true,note:clean(p?.note,8000)}]));}
export function exportLibrary(lib,prefs={},creatorPrefs={}){return {...lib,exportedAt:new Date().toISOString(),creators:Object.fromEntries(buildCreators(lib.videos,creatorPrefs,lib.followedCreators).filter(c=>c.tier||c.reason).map(c=>[c.key,{tier:c.tier,reason:c.reason}])),videos:lib.videos.map(({key,...v})=>({...v,...(prefs[key]?{personal:prefs[key]}:{})}))};}
